#include <bits/stdc++.h>
using namespace std;

struct Combo {
    int sum, mx, mn, id;
};

bool cmp(const Combo &a, const Combo &b) {
    if (a.sum != b.sum) {
        return a.sum < b.sum;
    }
    if (a.mx != b.mx) {
        return a.mx < b.mx;
    }
    if (a.mn != b.mn) {
        return a.mn < b.mn;
    }
    return a.id < b.id;
}

int main() {
    int n, k;
    cin >> n >> k;

    vector<Combo> boxes(n);
    for (int i = 0; i < n; i++) {
        boxes[i].sum = 0;
        boxes[i].mx = -1;
        boxes[i].mn = 1000000000;
        boxes[i].id = i + 1;

        for (int j = 0; j < k; j++) {
            int value;
            cin >> value;
            boxes[i].sum += value;
            boxes[i].mx = max(boxes[i].mx, value);
            boxes[i].mn = min(boxes[i].mn, value);
        }
    }

    sort(boxes.begin(), boxes.end(), cmp);

    for (int i = 0; i < n; i++) {
        cout << boxes[i].id;
        if (i + 1 < n) {
            cout << " ";
        }
    }
    cout << endl;
    return 0;
}

