#include <bits/stdc++.h>
using namespace std;

const int N = 1005;
char mat[N][N];
int gain[N][N];
const int d[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

int main() {
    int n, m;
    scanf("%d%d", &n, &m);

    for (int i = 1; i <= n; i++) {
        scanf("%s", mat[i] + 1);
    }

    int base = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            int blocked_count = 0;
            int blocked_dir = -1;

            for (int k = 0; k < 4; k++) {
                int nx = i + d[k][0];
                int ny = j + d[k][1];
                if (mat[nx][ny] == '#') {
                    blocked_count++;
                    blocked_dir = k;
                }
            }

            if (mat[i][j] == '.' && blocked_count == 0) {
                base++;
            } else if (mat[i][j] == '.' && blocked_count == 1) {
                int nx = i + d[blocked_dir][0];
                int ny = j + d[blocked_dir][1];
                gain[nx][ny]++;
            } else if (mat[i][j] == '#' && blocked_count == 0) {
                gain[i][j]++;
            }
        }
    }

    int extra = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            extra = max(extra, gain[i][j]);
        }
    }

    printf("%d\n", base + extra);
    return 0;
}

