const int N = 55;
int w[N][N];

bool check(int xa, int ya, int xb, int yb) {
    int count[2] = {0, 0};
    for (int i = xa; i <= xb; i++) {
        for (int j = ya; j <= yb; j++) {
            count[w[i][j]]++;
        }
    }
    return count[0] == count[1];
}

int main() {
    int n, m;
    cin >> n >> m;

    for (int i = 1; i <= n; i++) {
        string s;
        cin >> s;
        for (int j = 1; j <= m; j++) {
            w[i][j] = s[j - 1] - '0';
        }
    }

    int ans = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= m; j++) {
            for (int ii = i; ii <= n; ii++) {
                for (int jj = j; jj <= m; jj++) {
                    if (check(i, j, ii, jj)) {
                        ans = max(ans, (ii - i + 1) * (jj - j + 1));
                    }
                }
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

